-- 1) wipe the managed subjects' actions for the seeded roles DELETE FROM role_permission_actions rpa USING role_permissions rp, role r, permission p WHERE rpa.role_permission_id = rp.id AND r.id = rp.role_id AND p.id = rp.permission_id AND r.name IN (SELECT DISTINCT role_name FROM role_matrix_tmp) AND upper(p.subject) IN ('FORM058', 'FORM0581', 'FORM129', 'CARD', 'ACT', 'REPORT', 'REPORT_ENTRY');
-- 2) role_permissions rows (the unique key is role_id + permission_id) INSERT INTO role_permissions (role_id, permission_id, version, created_at, updated_at) SELECT DISTINCT r.id, p.id, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM role_matrix_tmp m JOIN role r ON r.name = m.role_name JOIN permission p ON upper(p.subject) = m.subject ON CONFLICT (role_id, permission_id) DO NOTHING;
-- 3) the matrix actions INSERT INTO role_permission_actions (role_permission_id, action_id) SELECT DISTINCT rp.id, a.id FROM role_matrix_tmp m JOIN role r ON r.name = m.role_name JOIN permission p ON upper(p.subject) = m.subject JOIN role_permissions rp ON rp.role_id = r.id AND rp.permission_id = p.id JOIN action a ON upper(a.code) = m.action ON CONFLICT (role_permission_id, action_id) DO NOTHING;
DROP TABLE role_matrix_tmp;
